import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceIconsLogicValues {
    sourceIcons: Record<string, string> | null
    sourceIconsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceIconsLogicActions {
    loadSourceIcons: () => any
    loadSourceIconsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSourceIconsSuccess: (
        sourceIcons: Record<string, string> | null,
        payload?: any
    ) => {
        sourceIcons: Record<string, string> | null
        payload?: any
    }
}

export type sourceIconsLogicType = MakeLogicType<sourceIconsLogicValues, sourceIconsLogicActions>

// A source-type-to-icon-path map, kept separate from `availableSourcesLogic` on purpose: rendering a
// source icon only needs one string per source, while the full catalog carries every field schema and
// is over 1 MB. Icon-only surfaces (the SQL editor database tree, the source tables) mount this instead,
// so they no longer download the whole catalog to pick an image.
export const sourceIconsLogic = kea<sourceIconsLogicType>([
    path(['products', 'dataWarehouse', 'sourceIconsLogic']),
    loaders({
        sourceIcons: [
            null as Record<string, string> | null,
            {
                loadSourceIcons: async () => {
                    // A missing icon map degrades to the local fallbacks in `SourceIcon`, so a failure
                    // here must never throw onto whatever page mounted the icon (e.g. the SQL editor).
                    try {
                        return await api.externalDataSources.sourceIcons()
                    } catch {
                        return null
                    }
                },
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSourceIcons()
    }),
])
